var maxJumps = function(arr, d) {
    const n = arr.length;
    const dp = new Array(n);

    const dfs = (pos) => {
        if (dp[pos] !== undefined) {
            return dp[pos];
        }

        let max = 1;

        for (let i = 1; i <= d; i++) {
            if (pos - i < 0 || arr[pos - i] >= arr[pos]) break;

            max = Math.max(max, dfs(pos - i) + 1);
        }

        for (let i = 1; i <= d; i++) {
            if (pos + i >= n || arr[pos + i] >= arr[pos]) break;

            max = Math.max(max, dfs(pos + i) + 1);
        }

        dp[pos] = max;
        return max;
    };

    let res = 1;

    for (let i = 0; i < n; i++) {
        res = Math.max(res, dfs(i));
    }

    return res;
};
